function socialVoteForm(string $kind,string $target,string $owner): void {$u=socialUser();$r=socialRating($kind,$target);echo '<section class="social-card"><h2>'.e(socialT($kind==='trip'?'rate_trip':'rate_member')).'</h2><p>'.($r['count']?'★ '.number_format((float)$r['average'],1).' / 5 · '.(int)$r['count']:e(socialT('no_ratings'))).'</p><small>'.e(socialT('ratings_note')).'</small>';if($u&&$u['id']!==$owner){$mine=socialQuery('SELECT score FROM member_ratings WHERE kind=? AND target=? AND voter=?',[$kind,$target,$u['id']])->fetchColumn();echo '<form method="post">'.csrf().'<input type="hidden" name="action" value="rate"><input type="hidden" name="kind" value="'.e($kind).'"><input type="hidden" name="target" value="'.e($target).'"><fieldset><legend>'.e(socialT('ratings')).'</legend><div class="social-stars" dir="ltr">';for($i=1;$i<=5;$i++)echo '<label><input type="radio" name="score" value="'.$i.'" required '.($mine==$i?'checked':'').'>'.$i.' ★</label>';echo '</div></fieldset><button class="button">'.e(socialT('rate')).'</button></form>';}elseif(!$u)echo '<a href="'.e(languageUrl('/community/account/',siteLanguage())).'">'.e(socialT('login_required')).'</a>';echo '</section>';}
function socialReportForm(string $kind,string $id): void {if(!socialUser())return;echo '<button type="button" data-cr-report="'.e($id).'" data-cr-kind="'.e($kind).'">'.e(crT('report')).'</button>';}

